<?php
declare(strict_types=1);
require_once dirname(__DIR__,2).'/app/helpers/attendance.php';
$user=require_role('admin','staf_bkk');
try{[$filters,$where,$params]=attendance_filters($_GET);}catch(InvalidArgumentException $exception){http_response_code(400);exit(e($exception->getMessage()));}
$from=' FROM attendance_records r JOIN attendance_events e ON e.id=r.event_id JOIN siswa s ON s.id=r.siswa_id WHERE '.$where;
$total=(int)panel_query('SELECT COUNT(DISTINCT r.siswa_id)'.$from,$params)->fetchColumn();
$pages=max(1,(int)ceil($total/25));$page=min($pages,positive_id($_GET['page']??'1')??1);
$rows=panel_query("SELECT s.id,s.nis,s.nama,s.kelas,COUNT(*) AS kegiatan,SUM(r.status='hadir') AS hadir,SUM(r.status='izin') AS izin,SUM(r.status='sakit') AS sakit,SUM(r.status='alpa') AS alpa,SUM(r.status IS NULL) AS belum".$from.' GROUP BY s.id,s.nis,s.nama,s.kelas ORDER BY s.nama,s.id LIMIT :limit OFFSET :offset',$params+['limit'=>25,'offset'=>($page-1)*25])->fetchAll();
panel_start($user,'Rekap absensi peserta','absensi');
?>
<div class="attendance-recap">
<header class="page-actions"><div><h1><?= panel_icon('tracer') ?> Rekap absensi peserta</h1><p>Jumlah kehadiran peserta berdasarkan kegiatan yang sesuai filter.</p></div><nav class="recap-actions" aria-label="Tindakan rekap"><a href="<?= e(base_url('panel/absensi/?'.http_build_query($filters))) ?>"><?= panel_icon('back') ?> Daftar kegiatan</a><a class="recap-export" href="<?= e(base_url('panel/ekspor.php?'.http_build_query(['jenis'=>'rekap']+$filters))) ?>"><?= panel_icon('download') ?> Rekap Excel</a></nav></header>
<?php attendance_filter_form($filters,'panel/absensi/rekap.php'); ?>
<div class="recap-table-heading"><h2><?= panel_icon('peserta') ?> Daftar peserta</h2><span><?= $total ?> peserta &middot; Halaman <?= $page ?> dari <?= $pages ?></span></div>
<details class="recap-help"><summary><?= panel_icon('message') ?> Cara membaca rekap</summary><p>Jumlah kegiatan mengikuti filter. Belum diisi dihitung terpisah dari Alpa. Identitas pada rekap mengikuti Data Peserta terbaru; identitas pada setiap kegiatan mengikuti riwayat saat kegiatan dibuat.</p></details>
<div class="table-scroll attendance-recap-sheet" data-vertical-list tabindex="0" role="region" aria-label="Rekap absensi peserta, gulir untuk melihat seluruh data"><table><thead><tr><th><?= panel_icon('peserta') ?> Nama peserta</th><th><?= panel_icon('program') ?> Kelas</th><th><?= panel_icon('calendar') ?> Kegiatan</th><?php foreach(attendance_statuses() as $key=>$label):?><th class="recap-status-<?= $key ?>"><?= e($label) ?></th><?php endforeach;?><th>Belum diisi</th></tr></thead><tbody><?php foreach($rows as $row):?><tr><td><strong><?= e($row['nama']) ?></strong></td><td><?= e($row['kelas']) ?></td><td><span class="recap-count recap-total"><?= (int)$row['kegiatan'] ?></span></td><?php foreach(attendance_statuses() as $key=>$label):?><td><span class="recap-count <?= (int)$row[$key]>0?'recap-status-'.$key:'recap-zero' ?>"><?= (int)$row[$key] ?></span></td><?php endforeach;?><td><span class="recap-count <?= (int)$row['belum']>0?'recap-pending':'recap-zero' ?>"><?= (int)$row['belum'] ?></span></td></tr><?php endforeach;?><?php if(!$rows):?><tr><td colspan="8" class="empty-panel">Belum ada peserta kegiatan yang sesuai. Ubah filter untuk melihat data lainnya.</td></tr><?php endif;?></tbody></table></div>
<?php if($pages>1):$start=max(1,min($page-2,$pages-4));$end=min($pages,$start+4); ?><nav class="pagination recap-pagination" aria-label="Halaman rekap"><?php if($page>1): ?><a href="<?= e(base_url('panel/absensi/rekap.php?'.http_build_query($filters+['page'=>$page-1]))) ?>"><?= panel_icon('back') ?> Sebelumnya</a><?php endif; ?><?php for($n=$start;$n<=$end;$n++): ?><a class="recap-page-number" aria-label="Halaman <?= $n ?>" <?= $n===$page?'aria-current="page"':'' ?> href="<?= e(base_url('panel/absensi/rekap.php?'.http_build_query($filters+['page'=>$n]))) ?>"><?= $n ?></a><?php endfor; ?><?php if($page<$pages): ?><a href="<?= e(base_url('panel/absensi/rekap.php?'.http_build_query($filters+['page'=>$page+1]))) ?>">Berikutnya <?= panel_icon('next') ?></a><?php endif; ?></nav><?php endif; ?>
</div>
<?php panel_end($user); ?>
